// th14_s4_w03 — TH14 v1.00b Stage 4 道中 MainSub00 入口 1000-1021
// 依赖: ECir00(12-45) / ECir00_at(47-146) / GirlD01(673-695) / GirlD01_at(697-741)

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// TH14 弹型：源 etSprite(1,4,8) / etSprite(0,8,6)，色号沿源
const TH14_BALL: int = 416;
const TH14_RICE: int = 480;

// ---- ECir00：12-45 -------------------------------------------------------
// 源 movePosRel(-192*A,0) + 两段 moveBezierRel(mode8 Hermite，各 120 帧)。
// 两段曲线的 REL 位移用任务私有 Hermite 槽逐帧取值，叠加出生点后写回世界位置。
async sub ecir(dir: int) {
    var a: fx = dir as fx;                    // 源 %A = ±1（MIRROR 决定方向）
    var bx: fx = $self_x;
    var by: fx = $self_y;
    set_invuln(65535);
    set_hurtbox(12fx);                        // setHurtbox(24,24) → r=12
    set_hitbox(8fx);                          // setHitbox(16,16) → r=8
    // flagSet(15)：0x2 体碰门在目标用 ENEMY_NO_BODY；0x4/0x8 屏外回收在本卡前 120 帧不会触发，0x1 未定义消费者
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(0, bx - 192fx * a, by, EASE_LINEAR);   // movePosRel(-192*A, 0)
    // moveBezierRel(120, 256A,-30, 160A,128, 0,0)
    hermite_start(0, -192fx * a, 160fx * a, 256fx * a, 0fx, 120);
    hermite_start(1, 0fx, 128fx, -30fx, 0fx, 120);
    for i in 0..120 {
        wait(1);
        move_to(0, bx + hermite_value(0), by + hermite_value(1), EASE_LINEAR);
    }
    set_enemy_flag(ENEMY_NO_BODY, 0);         // flagClear(15)（t=120）
    // moveBezierRel(120, 0,0, -220A,192, -200A,-228)
    hermite_start(0, 160fx * a, -220fx * a, 0fx, -200fx * a, 120);
    hermite_start(1, 128fx, 192fx, 0fx, -228fx, 120);
    spawn ecir_at();                          // @ECir00_at() async
    for j in 0..120 {
        wait(1);
        move_to(0, bx + hermite_value(0), by + hermite_value(1), EASE_LINEAR);
    }
    loop { wait(1000); }                       // 源 1048/1068 常驻等待
}

// ---- ECir00_at：47-146 ---------------------------------------------------
async sub ecir_at() {
    var rank: int = global(GVAR_RANK);
    var shots: int = 1;                       // diffI($A,1,1,1,8) 后 if($A--) → 执行 A 次
    var gap: int = 600;
    var lspd: fx = 2.7fx;                     // etSpeed(0, [-1],[-2])，两端同值
    var llen: fx = 128fx;                     // laserNew targetLength
    var n1: int = 1;                          // etCount(1, [-1], 1)
    var v1: fx = 2.0fx;                       // etSpeed(1, 1.0, [-1])，mode8 随机幅度
    if rank == RANK_NORMAL { gap = 50; lspd = 3.5fx; n1 = 3; v1 = 2.5fx; }
    if rank == RANK_HARD { gap = 10; lspd = 4.5fx; llen = 144fx; n1 = 5; v1 = 2.5fx; }
    if rank == RANK_LUNATIC { shots = 8; gap = 8; lspd = 5.0fx; llen = 160fx; n1 = 5; v1 = 3.0fx; }
    wait(10);
    for s in 0..shots {
        // etAngle(0, ANGLE_PLAYER,0) 后 laserOn(0)：每次发射现瞄自机
        var aim: angle = aim_player();
        // 700 Line：初长0→目标长 llen、生长/前移速率 etSpeed、源宽14（w<32 → 判定宽 2*w/4=7）
        // 判定段按 Line 规则 0.1L..0.9L；生长阶段近端固定 0.1L 为近似，出屏由 target 回收
        var h: int = laser(3, $self_x, $self_y, aim, 0fx, 7fx, 0, 9999, 0);
        lz_start(h, llen * 0.1fx);
        lz_speed(h, lspd, llen * 0.8fx);
        if rank >= RANK_NORMAL {
            // etNew(1); etAim(1,8)：随机角与随机速；etCount(n1,1)；etAngle(ANGLE_PLAYER, 18deg)
            var aim1: angle = aim_player();
            var spread: int = 18deg as int;
            for i in 0..n1 {
                var ra: int = rand(65536);    // RANDF2 → ±18deg
                var ang: angle = aim1 + (((spread * (ra - 32768)) / 32768) as angle);
                var rv: int = rand(65536);    // RANDF → 速度幅度
                var sp: fx = 1.0fx + ((((rv - 32768) as fx) / 65536 + 0.5fx) * v1);
                // etEx(1,0,2,1,…) ANIM a=1 的出生退位移：position -= 4*velocity
                _ = fire(TH14_BALL, 8, $self_x - 4fx * (sp * cos(ang)), $self_y - 4fx * (sp * sin(ang)), sp, ang, none, none);
            }
            // etNew(1); etAim(1,1)：固定扇形 2 路、间距 3deg → ±1.5deg；etSpeed(1,2.0,2.0)
            var aim2: angle = aim_player();
            _ = fire(TH14_BALL, 8, $self_x - 8fx * cos(aim2 + 273bam), $self_y - 8fx * sin(aim2 + 273bam), 2.0fx, aim2 + 273bam, none, none);
            _ = fire(TH14_BALL, 8, $self_x - 8fx * cos(aim2 - 273bam), $self_y - 8fx * sin(aim2 - 273bam), 2.0fx, aim2 - 273bam, none, none);
        }
        wait(gap);                            // 1332：wait(600/50/10/8)
    }
}

// ---- GirlD01：673-695 ----------------------------------------------------
async sub girld() {
    set_invuln(65535);
    set_hurtbox(16fx);                        // setHurtbox(32,32) → r=16
    set_hitbox(12fx);                         // setHitbox(24,24) → r=12
    move_vel(0, 90deg, 1.4fx, EASE_LINEAR);   // moveVel(pi/2, 1.4)
    move_speed(60, 0fx, EASE_QUAD_IN);        // moveSpeedTime(60, 1, 0.0)
    spawn girld_at();                         // @GirlD01_at() async
    wait(120);
    move_speed(80, 1fx, EASE_QUAD_IN);        // moveSpeedTime(80, 1, 1.0)
    wait(60);
    loop { wait(1000); }
}

// ---- GirlD01_at：697-741 -------------------------------------------------
async sub girld_at() {
    var rank: int = global(GVAR_RANK);
    var outs: int = 1;                        // diffI($A,1,2,3,4) 后 if($A--) → 执行 A 次
    var step_wait: int = 4;
    if rank == RANK_NORMAL { outs = 2; step_wait = 3; }
    if rank == RANK_HARD { outs = 3; step_wait = 2; }
    if rank == RANK_LUNATIC { outs = 4; step_wait = 1; }
    wait(60);
    for o in 0..outs {
        var b: int = 3641;                    // %B = 0.349066rad ≈ 20deg，逐次 *0.98
        var c: fx = 8fx;                      // %C：etOffsetRad 半径，逐次 +10
        for d in 0..15 {                      // $D=15 → 15 轮
            // etOffsetRad(0, B*RANDF2, C) → etAngle(90deg+RANDF2*6deg) → etSpeed(1+RANDF*1.5) → etOn
            var r1: int = rand(65536);
            var off1: angle = ((b * (r1 - 32768)) / 32768) as angle;
            var r2: int = rand(65536);
            var ang1: angle = 90deg + ((((6deg as int) * (r2 - 32768)) / 32768) as angle);
            var r3: int = rand(65536);
            var sp1: fx = 1.0fx + ((((r3 - 32768) as fx) / 65536 + 0.5fx) * 1.5fx);
            // etEx(0,0,2,1,…) ANIM a=1 的出生退位移：position -= 4*velocity
            _ = fire(TH14_RICE, 6, $self_x + c * cos(off1) - 4fx * (sp1 * cos(ang1)), $self_y + c * sin(off1) - 4fx * (sp1 * sin(ang1)), sp1, ang1, none, none);
            // 同轮第二发：etOffsetRad(0, B*RANDF2, -C)，角度/速度重新抽样
            var r4: int = rand(65536);
            var off2: angle = ((b * (r4 - 32768)) / 32768) as angle;
            var r5: int = rand(65536);
            var ang2: angle = 90deg + ((((6deg as int) * (r5 - 32768)) / 32768) as angle);
            var r6: int = rand(65536);
            var sp2: fx = 1.0fx + ((((r6 - 32768) as fx) / 65536 + 0.5fx) * 1.5fx);
            _ = fire(TH14_RICE, 6, $self_x - c * cos(off2) - 4fx * (sp2 * cos(ang2)), $self_y - c * sin(off2) - 4fx * (sp2 * sin(ang2)), sp2, ang2, none, none);
            c = c + 10fx;
            b = (b * 98) / 100;
            wait(step_wait);
        }
    }
}

// ---- 入口 MainSub00：1000-1021 ------------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-96fx, -32fx, 800, 0, 0, 0, girld);   // 1000
    wait(40);                                             // 1001
    var ax: fx = 0fx;                                     // 1002
    for i in 0..7 {                                       // 1003-1010（$H=7 → 7 次）
        _ = spawn_enemy(ax, 0fx, 150, 0, 0, 0, ecir(1));  // 1006（enmCreate，A=+1）
        wait(20);                                         // 1007
        ax = ax - 10fx;                                   // 1008
    }
    wait(130);                                            // 1011
    _ = spawn_enemy(0fx, -32fx, 800, 0, 0, 0, girld);     // 1012
    for pair in 0..7 {                                    // 1013-1021（$I=7 → 7 对）
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir(-1));    // 1016 enmCreateM
        wait(15);
        _ = spawn_enemy(0fx, 0fx, 150, 0, 0, 0, ecir(1));     // 1018 enmCreate
        wait(15);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
